export const ADMIN_HTML = "<!doctype html>\n<html lang=\"it\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"theme-color\" content=\"#17191b\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<meta name=\"apple-mobile-web-app-title\" content=\"MBV Admin\">\n<link rel=\"manifest\" href=\"__BASE__/manifest.webmanifest\">\n<link rel=\"icon\" href=\"__BASE__/icon-192.png\">\n<link rel=\"apple-touch-icon\" href=\"__BASE__/icon-192.png\">\n<title>MB Visual Admin</title>\n<style>\n  :root { --bg: #111315; --panel: #1a1d20; --panel2: #23272b; --line: #2f3439; --fg: #eceeef; --muted: #9aa1a8; --faint: #6d747b;\n    --accent: #f07d2e; --accent-fg: #1a1006; --ok: #5cb85c; --bad: #e0605a; --warn: #e3a33b; --r: 12px;\n    --top: env(safe-area-inset-top, 0px); --bottom: env(safe-area-inset-bottom, 0px); }\n  *, *::before, *::after { box-sizing: border-box; cursor: default !important; -webkit-tap-highlight-color: transparent; }\n  html, body { margin: 0; height: 100%; background: var(--bg); color: var(--fg); font: 15px/1.4 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; }\n  body { overscroll-behavior: none; }\n  button, input, select, textarea { font: inherit; color: inherit; }\n  .hide { display: none !important; }\n  .mono { font-family: ui-monospace, \"SF Mono\", Consolas, monospace; letter-spacing: .02em; }\n  .muted { color: var(--muted); } .faint { color: var(--faint); } .err { color: var(--bad); }\n  /* schermate a tutto schermo: accesso, protezione, blocco */\n  .screen { position: fixed; inset: 0; display: grid; place-items: center; padding: calc(24px + var(--top)) 22px calc(24px + var(--bottom)); background: var(--bg); z-index: 50; overflow: auto; }\n  .card-c { width: min(420px, 100%); text-align: center; display: grid; gap: 14px; }\n  .card-c img { width: 96px; height: 96px; margin: 0 auto; border-radius: 22px; }\n  .card-c h1 { margin: 0; font-size: 22px; } .card-c p { margin: 0; color: var(--muted); }\n  input.big { width: 100%; padding: 13px 14px; border-radius: 10px; border: 1px solid var(--line); background: var(--panel2); font-size: 17px; text-align: center; }\n  input.big:focus, .field input:focus, .field textarea:focus { outline: none; border-color: var(--accent); }\n  .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; padding: 0 18px; border-radius: 10px; border: 1px solid var(--line);\n    background: var(--panel2); font-weight: 600; }\n  .btn.p { background: var(--accent); border-color: var(--accent); color: var(--accent-fg); }\n  .btn.d { color: var(--bad); } .btn.w { width: 100%; } .btn:disabled { opacity: .5; }\n  .btn.s { min-height: 34px; padding: 0 12px; font-size: 13.5px; border-radius: 8px; }\n  .link { background: none; border: 0; color: var(--muted); text-decoration: underline; padding: 6px; }\n  /* app */\n  header { position: sticky; top: 0; z-index: 10; display: flex; align-items: center; gap: 10px; padding: calc(10px + var(--top)) 16px 10px; background: rgba(17, 19, 21, .94);\n    border-bottom: 1px solid var(--line); backdrop-filter: blur(8px); }\n  header h2 { margin: 0; font-size: 18px; flex: 1; }\n  header .conn { font-size: 12px; color: var(--faint); }\n  .iconbtn { width: 38px; height: 38px; border-radius: 10px; border: 0; background: var(--panel2); display: inline-grid; place-items: center; }\n  .iconbtn svg, nav svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n  main { padding: 14px 14px calc(86px + var(--bottom)); display: grid; gap: 12px; }\n  nav { position: fixed; left: 0; right: 0; bottom: 0; z-index: 10; display: grid; grid-template-columns: repeat(4, 1fr); padding: 6px 6px calc(6px + var(--bottom));\n    background: rgba(26, 29, 32, .97); border-top: 1px solid var(--line); }\n  nav button { position: relative; display: grid; justify-items: center; gap: 2px; padding: 6px 0; border: 0; background: none; color: var(--muted); font-size: 11.5px; }\n  nav button.on { color: var(--accent); }\n  nav .badge { position: absolute; top: 2px; left: calc(50% + 6px); }\n  .badge { min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; background: var(--bad); color: #fff; font-size: 11px; font-weight: 700; display: inline-grid; place-items: center; }\n  .cards { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n  .tile { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); padding: 12px 14px; }\n  .tile .n { font-size: 26px; font-weight: 700; } .tile .l { color: var(--muted); font-size: 13px; }\n  .tile.alert .n { color: var(--accent); }\n  .box { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); overflow: hidden; }\n  .row { padding: 12px 14px; border-bottom: 1px solid var(--line); display: grid; gap: 4px; }\n  .row:last-child { border-bottom: 0; }\n  .row.unread { box-shadow: inset 3px 0 0 var(--accent); background: rgba(240, 125, 46, .06); }\n  .row .top { display: flex; align-items: baseline; gap: 8px; } .row .top b { flex: 1; min-width: 0; }\n  .row .t { font-size: 12px; color: var(--faint); white-space: nowrap; }\n  .row.tap:active { background: var(--panel2); }\n  .sec { display: flex; align-items: center; gap: 8px; margin: 6px 2px -2px; }\n  .sec h3 { margin: 0; font-size: 15px; flex: 1; }\n  .chip { font-size: 11.5px; padding: 1px 8px; border-radius: 9px; border: 1px solid; white-space: nowrap; }\n  .chip.active, .chip.done { color: var(--ok); } .chip.revoked, .chip.closed { color: var(--muted); } .chip.replaced { color: var(--warn); } .chip.pending, .chip.open { color: var(--bad); }\n  .search { display: flex; gap: 8px; align-items: center; }\n  .search input[type=search] { flex: 1; min-width: 0; padding: 11px 12px; border-radius: 10px; border: 1px solid var(--line); background: var(--panel2); }\n  .toggle { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13.5px; }\n  .toggle input { width: 20px; height: 20px; accent-color: var(--accent); }\n  .actions { display: flex; flex-wrap: wrap; gap: 8px; }\n  .fab { position: fixed; right: 16px; bottom: calc(76px + var(--bottom)); z-index: 11; height: 52px; padding: 0 20px; border-radius: 26px; border: 0; background: var(--accent);\n    color: var(--accent-fg); font-weight: 700; box-shadow: 0 10px 24px -8px rgba(240, 125, 46, .7); }\n  .note { font-size: 13px; color: var(--muted); }\n  .banner { background: var(--panel2); border: 1px solid var(--line); border-radius: var(--r); padding: 12px 14px; display: grid; gap: 6px; }\n  .banner ol { margin: 0; padding-left: 20px; color: var(--muted); }\n  /* foglio dal basso (dettaglio licenza, moduli) */\n  .back { position: fixed; inset: 0; z-index: 40; background: rgba(0, 0, 0, .55); display: flex; align-items: flex-end; }\n  .sheet { width: 100%; max-height: 92vh; overflow: auto; background: var(--panel); border-radius: 18px 18px 0 0; padding: 8px 16px calc(18px + var(--bottom)); display: grid; gap: 12px; }\n  .sheet .grab { width: 40px; height: 5px; border-radius: 3px; background: var(--line); margin: 2px auto 4px; }\n  .sheet h3 { margin: 0; font-size: 18px; }\n  .kv { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; } .kv dt { color: var(--muted); } .kv dd { margin: 0; word-break: break-word; }\n  .keybox { display: grid; gap: 8px; padding: 12px; border-radius: 10px; background: var(--panel2); text-align: center; }\n  .keybox .mono { font-size: 16px; }\n  .field { display: grid; gap: 4px; font-size: 13px; color: var(--muted); }\n  .field input, .field textarea { width: 100%; min-width: 0; padding: 11px 12px; border-radius: 10px; border: 1px solid var(--line); background: var(--panel2); color: var(--fg); font-size: 16px; }\n  .grid2 { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; }\n  .dev { display: flex; align-items: center; gap: 10px; padding: 10px 0; border-top: 1px solid var(--line); }\n  .dev > div { flex: 1; min-width: 0; }\n  #toast { position: fixed; left: 16px; right: 16px; bottom: calc(80px + var(--bottom)); z-index: 60; padding: 12px 14px; border-radius: 10px; background: #2b3035; border: 1px solid var(--line);\n    box-shadow: 0 10px 30px rgba(0, 0, 0, .5); }\n  #toast.bad { border-color: var(--bad); }\n  .empty { padding: 18px 14px; color: var(--muted); text-align: center; }\n</style>\n</head>\n<body>\n<!-- accesso -->\n<div class=\"screen hide\" id=\"s-login\"><div class=\"card-c\">\n  <img src=\"__BASE__/icon-192.png\" alt=\"\"><h1>MB Visual Admin</h1>\n  <p>Inserisci il codice di 6 cifre mostrato da MB Visual Admin sul PC (Impostazioni → App per telefono) oppure il codice di gestione.</p>\n  <input class=\"big mono\" id=\"code\" type=\"password\" inputmode=\"text\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" placeholder=\"Codice\">\n  <div class=\"err\" id=\"login-err\"></div>\n  <button class=\"btn p w\" id=\"login-go\">Accedi</button>\n</div></div>\n<!-- protezione con impronta / PIN -->\n<div class=\"screen hide\" id=\"s-protect\"><div class=\"card-c\">\n  <img src=\"__BASE__/icon-192.png\" alt=\"\"><h1>Proteggi l'accesso</h1>\n  <p>Ogni volta che apri l'app ti verra' chiesta l'impronta, il volto o il PIN di questo telefono. Chi prende il telefono sbloccato non puo' gestire le licenze.</p>\n  <div class=\"err\" id=\"protect-err\"></div>\n  <button class=\"btn p w\" id=\"protect-go\">Attiva impronta / PIN</button>\n  <button class=\"link\" id=\"protect-skip\">Non ora</button>\n</div></div>\n<!-- bloccata -->\n<div class=\"screen hide\" id=\"s-lock\"><div class=\"card-c\">\n  <img src=\"__BASE__/icon-192.png\" alt=\"\"><h1>App bloccata</h1>\n  <p>Sblocca con l'impronta, il volto o il PIN del telefono.</p>\n  <div class=\"err\" id=\"lock-err\"></div>\n  <button class=\"btn p w\" id=\"lock-go\">Sblocca</button>\n  <button class=\"link\" id=\"lock-out\">Esci e accedi con il codice</button>\n</div></div>\n\n<div id=\"app\" class=\"hide\">\n  <header><h2 id=\"title\">Panoramica</h2><span class=\"conn\" id=\"conn\"></span>\n    <button class=\"iconbtn\" id=\"refresh\" title=\"Aggiorna\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7\"/></svg></button></header>\n  <main id=\"main\"></main>\n  <button class=\"fab hide\" id=\"fab\">+ Nuova licenza</button>\n  <nav>\n    <button data-v=\"panoramica\" class=\"on\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 13h6V4H4zM14 20h6v-9h-6zM4 20h6v-3H4zM14 8h6V4h-6z\"/></svg>Panoramica</button>\n    <button data-v=\"licenze\"><svg viewBox=\"0 0 24 24\"><circle cx=\"8\" cy=\"15\" r=\"4\"/><path d=\"M11 12l9-9M17 6l3 3M15 8l2 2\"/></svg>Licenze</button>\n    <button data-v=\"richieste\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 5h16v11H8l-4 4z\"/></svg>Richieste<span class=\"badge hide\" id=\"nreq\"></span></button>\n    <button data-v=\"impostazioni\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M4.9 19.1L7 17M17 7l2.1-2.1\"/></svg>Impostazioni</button>\n  </nav>\n</div>\n<div id=\"toast\" class=\"hide\"></div>\n\n<script>\n\"use strict\";\nconst BASE = \"__BASE__\";\nconst $ = id => document.getElementById(id);\nconst esc = s => String(s ?? \"\").replace(/[&<>\"']/g, c => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\nconst fmt = s => s ? new Date(s.replace(\" \", \"T\") + \"Z\").toLocaleString(\"it-IT\", { dateStyle: \"short\", timeStyle: \"short\" }) : \"\";\nconst b64u = buf => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\\+/g, \"-\").replace(/\\//g, \"_\").replace(/=+$/, \"\");\nconst unb64u = s => Uint8Array.from(atob(s.replace(/-/g, \"+\").replace(/_/g, \"/\") + \"===\".slice((s.length + 3) % 4)), c => c.charCodeAt(0));\nconst KIND = { activation: \"Attivazione\", change: \"Cambio dispositivo\", change_pending: \"Cambio DA APPROVARE\", report: \"Segnalazione\", limit: \"Limite raggiunto\",\n  invalid_key: \"Chiave non valida\", revoked_use: \"Licenza non valida in uso\", admin_login: \"Accesso alla gestione\" };\nconst STATO = { active: \"attiva\", revoked: \"revocata\", replaced: \"sostituita\", open: \"aperta\", pending: \"in attesa\", done: \"completata\", closed: \"chiusa\" };\nconst standalone = matchMedia(\"(display-mode: standalone)\").matches || navigator.standalone === true;\nconst ios = /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === \"MacIntel\" && navigator.maxTouchPoints > 1);\nlet state = {}, view = (location.hash.slice(1) || \"panoramica\"), data = null, showAll = false, query = \"\";\nif (![\"panoramica\", \"licenze\", \"richieste\", \"impostazioni\"].includes(view)) view = \"panoramica\";\n\nfunction toast(t, bad) { const e = $(\"toast\"); e.textContent = t; e.className = bad ? \"bad\" : \"\"; clearTimeout(e._h); e._h = setTimeout(() => e.classList.add(\"hide\"), 3800); }\nasync function api(method, path, body) {\n  const r = await fetch(`${BASE}/api/${path}`, { method, credentials: \"same-origin\", cache: \"no-store\",\n    headers: body !== undefined ? { \"content-type\": \"application/json\" } : {}, body: body !== undefined ? JSON.stringify(body) : undefined });\n  const d = await r.json().catch(() => ({ ok: false, errore: \"Risposta non valida dal server (\" + r.status + \")\" }));\n  if (r.status === 423) { show(\"lock\"); throw new Error(d.errore); }\n  if (r.status === 401 && d.stato === \"accesso\") { show(\"login\"); throw new Error(d.errore); }\n  if (!r.ok || d.ok === false) throw new Error(d.errore || \"Errore \" + r.status);\n  return d;\n}\nfunction show(s) {\n  for (const id of [\"login\", \"protect\", \"lock\"]) $(\"s-\" + id).classList.toggle(\"hide\", id !== s);\n  $(\"app\").classList.toggle(\"hide\", s !== \"app\");\n  if (s === \"lock\") setTimeout(() => $(\"lock-go\").focus(), 50);\n}\nconst deviceName = () => (/android/i.test(navigator.userAgent) ? \"Android\" : ios ? \"iPhone/iPad\" : \"Telefono\") + \" \" + new Date().toLocaleDateString(\"it-IT\");\nconst waSupported = async () => !!(window.PublicKeyCredential && await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable?.().catch(() => false));\n\n// ------------------------------------------------------------ avvio\nasync function start() {\n  if (\"serviceWorker\" in navigator) navigator.serviceWorker.register(`${BASE}/sw.js`, { scope: `${BASE}/` }).catch(() => {});\n  try { state = await api(\"GET\", \"state\"); } catch (e) { $(\"login-err\").textContent = e.message; show(\"login\"); return; }\n  const pair = new URLSearchParams(location.search).get(\"abbina\");\n  if (pair) history.replaceState(null, \"\", `${BASE}/` + location.hash);\n  if (!state.accesso) { if (pair && /^\\d{6}$/.test(pair)) return doLogin({ pair }); show(\"login\"); return; }\n  if (state.bloccata) { show(\"lock\"); return; }\n  if (!state.impronta && await waSupported() && localStorage.getItem(\"mbva-noimpronta\") !== \"1\") { show(\"protect\"); return; }\n  openApp();\n}\nasync function doLogin(body) {\n  $(\"login-err\").textContent = \"\"; $(\"login-go\").disabled = true;\n  try {\n    await api(\"POST\", \"login\", { ...body, name: deviceName() });\n    $(\"code\").value = \"\";\n    state = await api(\"GET\", \"state\");\n    if (!state.impronta && await waSupported()) show(\"protect\"); else openApp();\n  } catch (e) { $(\"login-err\").textContent = e.message; show(\"login\"); } finally { $(\"login-go\").disabled = false; }\n}\n$(\"login-go\").onclick = () => { const v = $(\"code\").value.trim(); if (!v) return; doLogin(/^\\d{6}$/.test(v.replace(/\\s/g, \"\")) ? { pair: v.replace(/\\s/g, \"\") } : { code: v }); };\n$(\"code\").addEventListener(\"keydown\", e => { if (e.key === \"Enter\") $(\"login-go\").click(); });\n\nasync function registerPasskey() {\n  const o = (await api(\"POST\", \"wa/reg-options\", {})).publicKey;\n  const cred = await navigator.credentials.create({ publicKey: { ...o, challenge: unb64u(o.challenge), user: { ...o.user, id: unb64u(o.user.id) } } });\n  await api(\"POST\", \"wa/reg\", { clientDataJSON: b64u(cred.response.clientDataJSON), attestationObject: b64u(cred.response.attestationObject) });\n}\n$(\"protect-go\").onclick = async () => {\n  $(\"protect-err\").textContent = \"\";\n  try { await registerPasskey(); localStorage.removeItem(\"mbva-noimpronta\"); toast(\"Accesso protetto con impronta / PIN\"); openApp(); }\n  catch (e) { $(\"protect-err\").textContent = e.name === \"NotAllowedError\" ? \"Operazione annullata.\" : e.message; }\n};\n$(\"protect-skip\").onclick = () => { localStorage.setItem(\"mbva-noimpronta\", \"1\"); openApp(); };\nasync function doUnlock() {\n  $(\"lock-err\").textContent = \"\"; $(\"lock-go\").disabled = true;\n  try {\n    const o = (await api(\"POST\", \"wa/unlock-options\", {})).publicKey;\n    const cred = await navigator.credentials.get({ publicKey: { ...o, challenge: unb64u(o.challenge), allowCredentials: o.allowCredentials.map(c => ({ ...c, id: unb64u(c.id) })) } });\n    await api(\"POST\", \"wa/unlock\", { id: cred.id, clientDataJSON: b64u(cred.response.clientDataJSON), authenticatorData: b64u(cred.response.authenticatorData), signature: b64u(cred.response.signature) });\n    state.bloccata = false; openApp();\n  } catch (e) { $(\"lock-err\").textContent = e.name === \"NotAllowedError\" ? \"Sblocco annullato.\" : e.message; } finally { $(\"lock-go\").disabled = false; }\n}\n$(\"lock-go\").onclick = doUnlock;\n$(\"lock-out\").onclick = async () => { try { await api(\"POST\", \"logout\", {}); } catch {} show(\"login\"); };\n\n// ------------------------------------------------------------ app\nlet timer = 0;\nfunction openApp() { show(\"app\"); setView(view); refresh(); clearInterval(timer); timer = setInterval(() => { if (!document.hidden) refresh(true); }, 60000); }\ndocument.querySelectorAll(\"nav button\").forEach(b => b.onclick = () => setView(b.dataset.v));\nfunction setView(v) {\n  view = v; history.replaceState(null, \"\", `${BASE}/#${v}`);\n  document.querySelectorAll(\"nav button\").forEach(b => b.classList.toggle(\"on\", b.dataset.v === v));\n  $(\"title\").textContent = { panoramica: \"Panoramica\", licenze: \"Licenze\", richieste: \"Richieste\", impostazioni: \"Impostazioni\" }[v];\n  $(\"fab\").classList.toggle(\"hide\", v !== \"licenze\");\n  scrollTo(0, 0); render();\n}\n$(\"refresh\").onclick = () => refresh();\nasync function refresh(quiet) {\n  try {\n    const [s, l, r, e] = await Promise.all([api(\"GET\", \"admin/summary\"), api(\"GET\", \"admin/licenses\"), api(\"GET\", \"admin/requests\"), api(\"GET\", \"admin/events?after=0\")]);\n    data = { s, lic: l.licenze, req: r.richieste, ev: e.avvisi.slice(-200).reverse() };\n    $(\"conn\").textContent = new Date().toLocaleTimeString(\"it-IT\", { hour: \"2-digit\", minute: \"2-digit\" });\n    const open = data.req.filter(x => x.status === \"open\" || x.status === \"pending\").length;\n    $(\"nreq\").textContent = open; $(\"nreq\").classList.toggle(\"hide\", !open);\n    navigator.setAppBadge?.(open + data.s.avvisi_non_letti).catch?.(() => {});\n    if (!open && !data.s.avvisi_non_letti) navigator.clearAppBadge?.().catch?.(() => {});\n    render();\n  } catch (x) { if (!quiet) toast(x.message, true); }\n}\ndocument.addEventListener(\"visibilitychange\", async () => {\n  if (document.hidden || $(\"app\").classList.contains(\"hide\")) return;\n  try { state = await api(\"GET\", \"state\"); } catch { return; }\n  if (!state.accesso) return show(\"login\");\n  if (state.bloccata) return show(\"lock\");\n  refresh(true);\n});\nnavigator.serviceWorker?.addEventListener(\"message\", e => { if (e.data?.vista) setView(e.data.vista); refresh(true); });\n\nfunction render() {\n  const m = $(\"main\");\n  if (view === \"impostazioni\") return renderSettings(m);\n  if (!data) { m.innerHTML = `<div class=\"empty\">Collegamento al server delle licenze...</div>`; return; }\n  if (view === \"panoramica\") {\n    const s = data.s, hint = standalone || localStorage.getItem(\"mbva-noinstalla\") === \"1\" ? \"\" : `<div class=\"banner\"><b>Installa l'app sulla schermata Home</b>\n      <ol>${ios ? \"<li>Tocca Condividi in Safari (quadrato con la freccia).</li><li>Scegli <b>Aggiungi alla schermata Home</b>.</li><li>Apri MBV Admin dalla Home e accedi con un nuovo codice di 6 cifre (l'app installata non vede l'accesso fatto in Safari).</li>\"\n        : \"<li>Apri il menu del browser (tre puntini).</li><li>Scegli <b>Installa app</b> o <b>Aggiungi a schermata Home</b>.</li>\"}</ol>\n      <div><button class=\"btn s\" onclick=\"localStorage.setItem('mbva-noinstalla','1');render()\">Nascondi</button></div></div>`;\n    m.innerHTML = hint + `<div class=\"cards\">${[[\"Licenze attive\", s.licenze], [\"PC attivi\", s.pc], [\"Cellulari attivi\", s.cellulari], [\"Richieste aperte\", s.richieste_aperte, s.richieste_aperte > 0]]\n      .map(([l, n, a]) => `<div class=\"tile${a ? \" alert\" : \"\"}\"><div class=\"n\">${n}</div><div class=\"l\">${l}</div></div>`).join(\"\")}</div>\n      <div class=\"sec\"><h3>Avvisi ${s.avvisi_non_letti ? `<span class=\"badge\">${s.avvisi_non_letti}</span>` : \"\"}</h3>${s.avvisi_non_letti ? `<button class=\"btn s\" id=\"readall\">Segna come letti</button>` : \"\"}</div>\n      <div class=\"box\">${data.ev.map(e => `<div class=\"row ${e.read ? \"\" : \"unread\"}\"><div class=\"top\"><b>${esc(KIND[e.kind] || e.kind)}</b><span class=\"t\">${fmt(e.created)}</span></div><div class=\"muted\">${esc(e.text)}</div></div>`).join(\"\")\n        || `<div class=\"empty\">Nessun avviso</div>`}</div>`;\n    $(\"readall\")?.addEventListener(\"click\", readAll);\n  }\n  if (view === \"licenze\") {\n    m.innerHTML = `<div class=\"search\"><input type=\"search\" id=\"q\" placeholder=\"Cerca cliente, chiave, email\" value=\"${esc(query)}\"></div>\n      <label class=\"toggle\"><input type=\"checkbox\" id=\"all\" ${showAll ? \"checked\" : \"\"}> anche sostituite e revocate</label><div class=\"box\" id=\"ll\"></div>`;\n    $(\"q\").oninput = e => { query = e.target.value; listLic(); };\n    $(\"all\").onchange = e => { showAll = e.target.checked; listLic(); };\n    listLic();\n  }\n  if (view === \"richieste\") {\n    m.innerHTML = `<div class=\"box\">${data.req.map(r => `<div class=\"row\"><div class=\"top\"><b>${r.type === \"change\" ? \"Cambio dispositivo\" : \"Segnalazione\"}</b><span class=\"chip ${r.status}\">${STATO[r.status] || r.status}</span></div>\n      <div>${esc(r.customer || r.license_key)} <span class=\"faint\">· ${fmt(r.created)}</span></div>${r.device_name ? `<div class=\"note\">da ${esc(r.device_name)}</div>` : \"\"}\n      ${r.message ? `<div class=\"muted\">${esc(r.message)}</div>` : \"\"}${r.new_key ? `<div class=\"note\">nuova chiave <span class=\"mono\">${esc(r.new_key)}</span></div>` : \"\"}\n      ${r.status === \"pending\" || r.status === \"open\" ? `<div class=\"actions\">${r.status === \"pending\" ? `<button class=\"btn s p\" data-a=\"approve\" data-id=\"${r.id}\">Approva</button>` : \"\"}<button class=\"btn s\" data-a=\"close\" data-id=\"${r.id}\">Chiudi</button></div>` : \"\"}</div>`).join(\"\")\n      || `<div class=\"empty\">Nessuna richiesta</div>`}</div>`;\n    m.querySelectorAll(\"[data-a]\").forEach(b => b.onclick = () => reqAct(+b.dataset.id, b.dataset.a));\n  }\n}\nfunction listLic() {\n  const q = query.toLowerCase();\n  const rows = data.lic.filter(l => (showAll || l.status === \"active\" || l.status === \"revoked\") && `${l.key} ${l.customer} ${l.email} ${l.notes}`.toLowerCase().includes(q));\n  $(\"ll\").innerHTML = rows.map(l => { const d = l.dispositivi.filter(x => x.status === \"active\");\n    return `<div class=\"row tap\" data-k=\"${esc(l.key)}\"><div class=\"top\"><b>${esc(l.customer || \"(senza nome)\")}</b><span class=\"chip ${l.status}\">${STATO[l.status]}</span></div>\n      <div class=\"mono note\">${esc(l.key)}</div><div class=\"note\">PC ${d.filter(x => x.kind === \"pc\").length}/${l.max_pc} · cellulari ${d.filter(x => x.kind === \"mobile\").length}/${l.max_mobile}</div></div>`; }).join(\"\")\n    || `<div class=\"empty\">Nessuna licenza</div>`;\n  $(\"ll\").querySelectorAll(\"[data-k]\").forEach(r => r.onclick = () => licSheet(r.dataset.k));\n}\n\n// ------------------------------------------------------------ fogli\nfunction sheet(html) {\n  const back = document.createElement(\"div\"); back.className = \"back\";\n  back.innerHTML = `<div class=\"sheet\"><div class=\"grab\"></div>${html}</div>`;\n  back.addEventListener(\"click\", e => { if (e.target === back) back.remove(); });\n  document.body.append(back); return back;\n}\nasync function copy(text, msg) { try { await navigator.clipboard.writeText(text); toast(msg || \"Copiato\"); } catch { toast(\"Copia non riuscita: tieni premuto sul testo per copiarlo\", true); } }\nasync function share(key, customer) {\n  const text = `Chiave di licenza MB Visual${customer ? \" per \" + customer : \"\"}: ${key}`;\n  if (navigator.share) { try { await navigator.share({ text }); } catch {} } else copy(text);\n}\nfunction keySheet(title, key, customer) {\n  const s = sheet(`<h3>${esc(title)}</h3><div class=\"keybox\"><span class=\"mono\">${esc(key)}</span><div class=\"actions\" style=\"justify-content:center\">\n    <button class=\"btn s\" id=\"k-copy\">Copia</button><button class=\"btn s p\" id=\"k-share\">Condividi</button></div></div><button class=\"btn w\" id=\"k-ok\">Chiudi</button>`);\n  s.querySelector(\"#k-copy\").onclick = () => copy(key, \"Chiave copiata\");\n  s.querySelector(\"#k-share\").onclick = () => share(key, customer);\n  s.querySelector(\"#k-ok\").onclick = () => s.remove();\n}\nfunction licSheet(key) {\n  const l = data.lic.find(x => x.key === key); if (!l) return;\n  const devs = l.dispositivi.filter(d => d.status === \"active\");\n  const s = sheet(`<h3>${esc(l.customer || \"(senza nome)\")}</h3>\n    <div class=\"keybox\"><span class=\"mono\">${esc(l.key)}</span><div class=\"actions\" style=\"justify-content:center\"><button class=\"btn s\" data-x=\"copy\">Copia</button><button class=\"btn s\" data-x=\"share\">Condividi</button></div></div>\n    <dl class=\"kv\"><dt>Stato</dt><dd><span class=\"chip ${l.status}\">${STATO[l.status]}</span>${l.replaced_by ? ` → <span class=\"mono\">${esc(l.replaced_by)}</span>` : \"\"}</dd>\n      ${l.email ? `<dt>Email</dt><dd>${esc(l.email)}</dd>` : \"\"}${l.notes ? `<dt>Note</dt><dd>${esc(l.notes)}</dd>` : \"\"}\n      <dt>Posti</dt><dd>PC ${devs.filter(d => d.kind === \"pc\").length}/${l.max_pc} · cellulari ${devs.filter(d => d.kind === \"mobile\").length}/${l.max_mobile}</dd>\n      <dt>Creata</dt><dd>${fmt(l.created)}${l.expires ? \" · scade \" + esc(l.expires) : \"\"}</dd></dl>\n    <div><b>Dispositivi</b>${devs.map(d => `<div class=\"dev\"><div><div>${d.kind === \"pc\" ? \"PC\" : \"Cellulare\"} · <b>${esc(d.name || \"-\")}</b></div>\n      <div class=\"note\">${esc([d.version, \"ultimo uso \" + fmt(d.last_seen)].filter(Boolean).join(\" · \"))}</div></div><button class=\"btn s d\" data-free=\"${d.id}\">Libera</button></div>`).join(\"\") || `<div class=\"note\">Nessun dispositivo attivo</div>`}</div>\n    <div class=\"actions\">${l.status === \"active\" ? `<button class=\"btn s\" data-x=\"edit\">Modifica</button><button class=\"btn s\" data-x=\"replace\">Nuova chiave</button><button class=\"btn s d\" data-x=\"revoke\">Revoca</button>`\n      : l.status === \"revoked\" ? `<button class=\"btn s\" data-x=\"reactivate\">Riattiva</button>` : \"\"}</div>`);\n  s.querySelectorAll(\"[data-free]\").forEach(b => b.onclick = async () => {\n    if (!confirm(\"Liberare il dispositivo? L'app su quel dispositivo si blocca e il posto torna disponibile.\")) return;\n    try { await api(\"POST\", `admin/devices/${b.dataset.free}/revoke`, {}); toast(\"Dispositivo liberato\"); s.remove(); await refresh(); licSheet(key); } catch (x) { toast(x.message, true); }\n  });\n  s.querySelectorAll(\"[data-x]\").forEach(b => b.onclick = async () => {\n    const x = b.dataset.x;\n    if (x === \"copy\") return copy(l.key, \"Chiave copiata\");\n    if (x === \"share\") return share(l.key, l.customer);\n    if (x === \"edit\") { s.remove(); return licForm(l); }\n    if (x === \"replace\" && !confirm(\"Generare una chiave nuova? Questa smettera' di funzionare su tutti i dispositivi.\")) return;\n    if (x === \"revoke\" && !confirm(\"Revocare la licenza? Tutte le app si bloccano.\")) return;\n    try { const r = await api(\"POST\", `admin/licenses/${encodeURIComponent(l.key)}/${x}`, {}); s.remove(); await refresh(); if (r.key) keySheet(\"Nuova chiave\", r.key, l.customer); else toast(\"Fatto\"); }\n    catch (e) { toast(e.message, true); }\n  });\n}\nfunction licForm(l) {\n  const s = sheet(`<h3>${l ? \"Modifica licenza\" : \"Nuova licenza\"}</h3>\n    <label class=\"field\">Cliente<input id=\"f-c\" value=\"${esc(l?.customer)}\" autocomplete=\"off\"></label>\n    <label class=\"field\">Email<input id=\"f-e\" type=\"email\" value=\"${esc(l?.email)}\" autocomplete=\"off\"></label>\n    <div class=\"grid2\"><label class=\"field\">PC<input id=\"f-p\" type=\"number\" min=\"1\" inputmode=\"numeric\" value=\"${l?.max_pc ?? 1}\"></label>\n      <label class=\"field\">Cellulari<input id=\"f-m\" type=\"number\" min=\"0\" inputmode=\"numeric\" value=\"${l?.max_mobile ?? 2}\"></label></div>\n    <label class=\"field\">Note<textarea id=\"f-n\" rows=\"2\">${esc(l?.notes)}</textarea></label>\n    <div class=\"err\" id=\"f-err\"></div><button class=\"btn p w\" id=\"f-ok\">${l ? \"Salva\" : \"Crea licenza\"}</button>`);\n  s.querySelector(\"#f-ok\").onclick = async () => {\n    const body = { customer: s.querySelector(\"#f-c\").value.trim(), email: s.querySelector(\"#f-e\").value.trim(), notes: s.querySelector(\"#f-n\").value.trim(),\n      max_pc: +s.querySelector(\"#f-p\").value || 1, max_mobile: Math.max(0, +s.querySelector(\"#f-m\").value || 0), expires: l?.expires || null };\n    if (!body.customer) { s.querySelector(\"#f-err\").textContent = \"Scrivi il nome del cliente.\"; return; }\n    try {\n      const r = await api(\"POST\", l ? `admin/licenses/${encodeURIComponent(l.key)}/update` : \"admin/licenses\", body);\n      s.remove(); await refresh();\n      if (!l) keySheet(\"Licenza creata\", r.key, body.customer); else toast(\"Licenza aggiornata\");\n    } catch (e) { s.querySelector(\"#f-err\").textContent = e.message; }\n  };\n}\n$(\"fab\").onclick = () => licForm(null);\nasync function reqAct(id, what) {\n  if (what === \"approve\" && !confirm(\"Approvare il cambio dispositivo? Verra' generata una chiave nuova e la vecchia smettera' di funzionare.\")) return;\n  try { const r = await api(\"POST\", `admin/requests/${id}/${what}`, {}); await refresh(); if (r.key) keySheet(\"Cambio approvato: nuova chiave\", r.key, data.req.find(x => x.id === id)?.customer); else toast(\"Fatto\"); }\n  catch (x) { toast(x.message, true); }\n}\nasync function readAll() { const last = Math.max(0, ...data.ev.map(e => e.id)); try { await api(\"POST\", \"admin/events/read\", { upto: last }); refresh(); } catch (x) { toast(x.message, true); } }\n\n// ------------------------------------------------------------ impostazioni\nasync function pushSub() { const reg = await navigator.serviceWorker?.getRegistration(`${BASE}/`); return reg ? reg.pushManager?.getSubscription() : null; }\nasync function renderSettings(m) {\n  const wa = await waSupported(), sub = await pushSub().catch(() => null);\n  const pushOk = \"PushManager\" in window && \"serviceWorker\" in navigator;\n  let phones = [];\n  try { phones = (await api(\"GET\", \"sessions\")).telefoni; } catch {}\n  if (view !== \"impostazioni\") return;\n  m.innerHTML = `<div class=\"sec\"><h3>Notifiche</h3></div><div class=\"box\"><div class=\"row\">\n      ${!state.notifiche ? `<div class=\"muted\">Notifiche non configurate sul server.</div>` : !pushOk ? `<div class=\"muted\">${ios && !standalone ? \"Su iPhone le notifiche arrivano solo all'app installata sulla schermata Home.\" : \"Questo browser non riceve notifiche.\"}</div>`\n        : sub ? `<div>Attive su questo telefono: attivazioni, richieste, segnalazioni e accessi alla gestione.</div><div class=\"actions\"><button class=\"btn s\" id=\"p-test\">Prova</button><button class=\"btn s d\" id=\"p-off\">Disattiva</button></div>`\n        : `<div class=\"muted\">${Notification.permission === \"denied\" ? \"Le notifiche sono bloccate nelle impostazioni del telefono per questa app.\" : \"Ricevi un avviso per ogni attivazione, richiesta o segnalazione.\"}</div>${Notification.permission === \"denied\" ? \"\" : `<div class=\"actions\"><button class=\"btn s p\" id=\"p-on\">Attiva notifiche</button></div>`}`}\n    </div></div>\n    <div class=\"sec\"><h3>Impronta / PIN</h3></div><div class=\"box\"><div class=\"row\">\n      ${state.impronta ? `<div>L'app chiede l'impronta, il volto o il PIN a ogni apertura e dopo ${10} minuti senza operazioni.</div><div class=\"actions\"><button class=\"btn s\" id=\"w-lock\">Blocca ora</button><button class=\"btn s d\" id=\"w-off\">Rimuovi</button></div>`\n        : wa ? `<div class=\"muted\">Non attivo: chi apre questo telefono sbloccato puo' gestire le licenze.</div><div class=\"actions\"><button class=\"btn s p\" id=\"w-on\">Attiva impronta / PIN</button></div>`\n        : `<div class=\"muted\">Questo telefono non offre impronta o PIN per le app web.</div>`}\n    </div></div>\n    <div class=\"sec\"><h3>Telefoni collegati</h3></div><div class=\"box\">${phones.map(p => `<div class=\"row\"><div class=\"top\"><b>${esc(p.nome)}${p.questo ? \" (questo)\" : \"\"}</b>${p.impronta ? `<span class=\"chip done\">impronta</span>` : \"\"}</div>\n      <div class=\"note\">collegato ${fmt(p.creato)} · ultimo uso ${fmt(p.ultimo)}</div>${p.questo ? \"\" : `<div class=\"actions\"><button class=\"btn s d\" data-off=\"${p.n}\">Scollega</button></div>`}</div>`).join(\"\") || `<div class=\"empty\">-</div>`}</div>\n    <button class=\"btn w d\" id=\"logout\">Esci da questo telefono</button>\n    <div class=\"note\" style=\"text-align:center\">Per collegare un altro telefono: MB Visual Admin sul PC → Impostazioni → App per telefono.</div>`;\n  $(\"p-on\")?.addEventListener(\"click\", async () => {\n    try {\n      if (await Notification.requestPermission() !== \"granted\") throw new Error(\"Permesso per le notifiche non concesso.\");\n      const reg = await navigator.serviceWorker.ready;\n      const s = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: unb64u(state.notifiche) });\n      await api(\"POST\", \"push/sub\", s.toJSON()); toast(\"Notifiche attive\"); renderSettings(m);\n    } catch (e) { toast(e.message, true); }\n  });\n  $(\"p-off\")?.addEventListener(\"click\", async () => { try { const s = await pushSub(); if (s) { await api(\"POST\", \"push/unsub\", { endpoint: s.endpoint }); await s.unsubscribe(); } toast(\"Notifiche disattivate\"); renderSettings(m); } catch (e) { toast(e.message, true); } });\n  $(\"p-test\")?.addEventListener(\"click\", async () => { try { const r = await api(\"POST\", \"push/test\", {}); toast(r.inviate ? \"Notifica di prova inviata\" : \"Invio non riuscito\", !r.inviate); } catch (e) { toast(e.message, true); } });\n  $(\"w-on\")?.addEventListener(\"click\", async () => { try { await registerPasskey(); state.impronta = true; localStorage.removeItem(\"mbva-noimpronta\"); toast(\"Impronta / PIN attivo\"); renderSettings(m); } catch (e) { toast(e.name === \"NotAllowedError\" ? \"Operazione annullata\" : e.message, true); } });\n  $(\"w-off\")?.addEventListener(\"click\", async () => { if (!confirm(\"Togliere la protezione con impronta / PIN?\")) return; try { await api(\"POST\", \"wa/remove\", {}); state.impronta = false; renderSettings(m); } catch (e) { toast(e.message, true); } });\n  $(\"w-lock\")?.addEventListener(\"click\", async () => { try { await api(\"POST\", \"lock\", {}); } catch {} show(\"lock\"); });\n  m.querySelectorAll(\"[data-off]\").forEach(b => b.onclick = async () => { if (!confirm(\"Scollegare quel telefono? Dovra' accedere di nuovo con un codice.\")) return; try { await api(\"POST\", `sessions/${b.dataset.off}/revoke`, {}); renderSettings(m); } catch (e) { toast(e.message, true); } });\n  $(\"logout\").onclick = async () => { if (!confirm(\"Uscire? Per rientrare servira' un codice.\")) return; try { const s = await pushSub(); if (s) await s.unsubscribe(); await api(\"POST\", \"logout\", {}); } catch {} show(\"login\"); };\n}\nstart();\n</script>\n</body>\n</html>\n";
export const ADMIN_SW = "// Service worker dell'app per telefono di MB Visual Admin: notifiche push e apertura dell'app dalla notifica.\n// Niente copie offline: i dati delle licenze si leggono sempre dal server.\nconst SCOPE = self.registration.scope;\nself.addEventListener(\"install\", () => self.skipWaiting());\nself.addEventListener(\"activate\", e => e.waitUntil(self.clients.claim()));\nself.addEventListener(\"push\", e => {\n  let d = {};\n  try { d = e.data ? e.data.json() : {}; } catch { d = { body: e.data ? e.data.text() : \"\" }; }\n  e.waitUntil(self.registration.showNotification(d.title || \"MB Visual Admin\", {\n    body: d.body || \"\", tag: d.tag, icon: SCOPE + \"icon-192.png\", badge: SCOPE + \"icon-192.png\", data: { url: d.url || SCOPE },\n  }));\n});\nself.addEventListener(\"notificationclick\", e => {\n  e.notification.close();\n  const url = new URL(e.notification.data?.url || SCOPE, SCOPE).href;\n  const vista = new URL(url).hash.slice(1);\n  e.waitUntil(self.clients.matchAll({ type: \"window\", includeUncontrolled: true }).then(list => {\n    const c = list.find(w => w.url.startsWith(SCOPE));\n    if (c) { c.postMessage({ vista }); return c.focus(); }\n    return self.clients.openWindow(url);\n  }));\n});\n";
